class Solution {
public:
    bool checkArray(vector<int>& nums, int k) {
        int n = nums.size();
        int curr_dec = 0;
        vector<int> diff(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            curr_dec += diff[i];
            int val = nums[i] - curr_dec;
            if (val < 0) return false;
            if (val > 0) {
                if (i + k > n) return false;
                curr_dec += val;
                diff[i + k] -= val;
            }
        }
        return true;
    }
};

