    public boolean checkArray(int[] nums, int k) {
        int n = nums.length;
        int currDec = 0;
        int[] diff = new int[n + 1];
        for (int i = 0; i < n; i++) {
            currDec += diff[i];
            int val = nums[i] - currDec;
            if (val < 0) return false;
            if (val > 0) {
                if (i + k > n) return false;
                currDec += val;
                diff[i + k] -= val;
            }
        }
        return true;
    }
}

