var checkArray = function(nums, k) {
    const n = nums.length;
    let currDec = 0;
    const diff = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        currDec += diff[i];
        const val = nums[i] - currDec;
        if (val < 0) return false;
        if (val > 0) {
            if (i + k > n) return false;
            currDec += val;
            diff[i + k] -= val;
        }
    }
    return true;
};
